												':root {\n  --blackBarHeight: 55px; }\n\n#gui-editor-workbench-root {\n  display: grid;\n  grid-template-rows: calc(100% - 55px);\n  height: 100%;\n  width: 100%;\n  background: #e2e2e2;\n  font: 14px "acumin-pro-condensed"; }\n\n.wait-screen {\n  display: grid;\n  justify-content: center;\n  align-content: center;\n  height: 100%;\n  width: 100%;\n  background: #464646;\n  opacity: 0.95;\n  color: white;\n  font: 24px "acumin-pro-condensed";\n  position: absolute;\n  top: 0;\n  left: 0; }\n  .wait-screen.hidden {\n    visibility: hidden; }\n\n#leftGrab {\n  width: 5px;\n  height: 100%;\n  cursor: ew-resize;\n  position: absolute;\n  right: -1px;\n  top: 0; }\n\n#rightGrab {\n  cursor: ew-resize;\n  width: 5px;\n  bottom: 0;\n  position: absolute;\n  top: 0;\n  left: 0; }\n\n.toolbarGrab {\n  background: #333333;\n  grid-row: 1 / span 3;\n  grid-column: 2;\n  height: 100%;\n  overflow-y: auto; }\n  .toolbarGrab .blackLine {\n    height: 16px;\n    background: black;\n    position: relative; }\n  .toolbarGrab .arrow {\n    color: white;\n    position: absolute; }\n  .toolbarGrab .toolbar-label {\n    color: white;\n    font-size: 18px;\n    display: grid;\n    align-items: center;\n    cursor: pointer;\n    user-select: none;\n    grid-template-columns: 1fr 20px;\n    grid-template-rows: 100%;\n    position: relative; }\n    .toolbarGrab .toolbar-label.active {\n      font-weight: bold;\n      font-size: 20px; }\n    .toolbarGrab .toolbar-label:hover {\n      background: var(--selectionGrey); }\n      .toolbarGrab .toolbar-label:hover .sub-items {\n        display: block; }\n  .toolbarGrab .toolbar-icon {\n    width: 40px;\n    height: 40px; }\n  .toolbarGrab.expanded .toolbar-content-sub1 {\n    column-count: 2; }\n\n.diagram-container {\n  position: relative;\n  display: grid;\n  grid-row: 1;\n  grid-column: 2;\n  background: #cccccc;\n  width: 100%;\n  height: 100%;\n  overflow: hidden; }\n  .diagram-container .diagram {\n    display: none;\n    width: 100%;\n    height: 100%; }\n\n.left-panel {\n  grid-row: 1 / span 2;\n  grid-column: 1;\n  display: grid;\n  grid-template-rows: 100%;\n  grid-template-columns: 1fr 50px;\n  position: relative;\n  overflow: hidden; }\n  .left-panel.expand {\n    grid-template-columns: 1fr 100px; }\n\n.right-panel {\n  grid-row: 1 / span 2;\n  grid-column: 3;\n  display: grid;\n  grid-template-rows: 1fr 40px auto 40px;\n  grid-template-columns: 100%;\n  overflow-y: auto;\n  position: relative; }\n  .right-panel #propertyTab {\n    grid-row: 1;\n    grid-column: 1; }\n  .right-panel .button {\n    display: grid;\n    justify-content: center;\n    align-content: center;\n    height: auto;\n    width: calc(100% / 7);\n    cursor: pointer; }\n    .right-panel .button:hover {\n      background: #337ab7;\n      color: white;\n      opacity: 0.8; }\n    .right-panel .button.selected {\n      background: #337ab7;\n      color: white; }\n    .right-panel .button.align {\n      justify-content: stretch;\n      text-align: center; }\n\n.blocker {\n  visibility: hidden;\n  position: absolute;\n  width: calc(100% - 40px);\n  height: 100%;\n  top: 0;\n  left: 0;\n  background: rgba(20, 20, 20, 0.95);\n  font-family: "acumin-pro-condensed", sans-serif;\n  color: white;\n  font-size: 24px;\n  display: grid;\n  align-content: center;\n  justify-content: center;\n  user-select: none;\n  padding: 20px;\n  text-align: center; }\n\n#log-console {\n  grid-row: 2;\n  grid-column: 4;\n  display: none; }\n\n.gizmo * {\n  user-select: none; }\n\n.gizmo .bounding-box-line {\n  background-color: black;\n  position: absolute;\n  line-height: 1px;\n  height: 1px;\n  pointer-events: none; }\n\n.gizmo .scale-point-container {\n  position: absolute;\n  width: 30px;\n  height: 30px; }\n  .gizmo .scale-point-container .scale-point {\n    top: 10px;\n    left: 10px;\n    position: absolute;\n    width: 10px;\n    height: 10px;\n    background: transparent;\n    outline: #7d7d7d 2px solid; }\n  .gizmo .scale-point-container .rotate-click-area {\n    width: 20px;\n    height: 20px;\n    position: absolute; }\n  .gizmo .scale-point-container .scale-click-area {\n    width: 20px;\n    height: 20px;\n    position: absolute; }\n\n.gizmo .pivot-point {\n  width: 30px;\n  height: 30px;\n  background: transparent;\n  position: absolute; }\n\n#workbench-canvas {\n  position: relative; }\n\n.artboard-stroke {\n  outline: 1px solid black;\n  position: absolute;\n  z-index: 2;\n  pointer-events: none; }\n\n.artboard-background {\n  position: absolute;\n  background: repeating-conic-gradient(#e2e2e2 0% 25%, white 0% 50%) 50%/10px 10px;\n  width: 100%;\n  height: 100%; }\n',
